/**
 * URL Validation Utility
 * Comprehensive security checks for user-submitted URLs
 */

// Known malicious TLDs and domains (can be extended)
const BLOCKED_DOMAINS = new Set([
  'bit.ly', // Prevent nested shorteners
  'tinyurl.com',
  'goo.gl',
  't.co',
  'ow.ly',
  'is.gd',
  'buff.ly',
  'adf.ly',
  'grabify.link', // IP logger
  'iplogger.org',
  'blasze.tk',
  '2no.co',
]);

const BLOCKED_TLDS = new Set([
  '.tk', // Free TLDs often used for phishing
  '.ml',
  '.ga',
  '.cf',
  '.gq',
]);

// Private/local IP ranges (RFC 1918, RFC 4193, localhost)
const PRIVATE_IP_PATTERNS = [
  /^127\./,                    // 127.0.0.0/8 - Loopback
  /^10\./,                     // 10.0.0.0/8 - Private
  /^172\.(1[6-9]|2[0-9]|3[0-1])\./, // 172.16.0.0/12 - Private
  /^192\.168\./,               // 192.168.0.0/16 - Private
  /^169\.254\./,               // 169.254.0.0/16 - Link-local
  /^fc[0-9a-f]{2}:/i,          // fc00::/7 - IPv6 ULA
  /^fe80:/i,                   // fe80::/10 - IPv6 Link-local
  /^::1$/,                     // ::1 - IPv6 loopback
  /^localhost$/i,
];

export interface URLValidationResult {
  isValid: boolean;
  error?: string;
  sanitizedUrl?: string;
}

/**
 * Validates and sanitizes a URL with comprehensive security checks
 * @param urlString - The URL to validate
 * @param maxLength - Maximum allowed URL length (default: 2048)
 * @returns Validation result with sanitized URL or error message
 */
export function validateUrl(
  urlString: string,
  maxLength: number = 2048
): URLValidationResult {
  // Basic checks
  if (!urlString || typeof urlString !== 'string') {
    return { isValid: false, error: 'URL is required' };
  }

  // Trim whitespace
  const trimmedUrl = urlString.trim();

  // Length check
  if (trimmedUrl.length > maxLength) {
    return {
      isValid: false,
      error: `URL exceeds maximum length of ${maxLength} characters`,
    };
  }

  if (trimmedUrl.length < 10) {
    return { isValid: false, error: 'URL is too short' };
  }

  // Try to parse URL
  let parsedUrl: URL;
  try {
    parsedUrl = new URL(trimmedUrl);
  } catch {
    return { isValid: false, error: 'Invalid URL format' };
  }

  // Protocol validation - only allow http and https
  if (!['http:', 'https:'].includes(parsedUrl.protocol)) {
    return {
      isValid: false,
      error: 'Only HTTP and HTTPS protocols are allowed',
    };
  }

  // Check for private/local IP addresses
  const hostname = parsedUrl.hostname.toLowerCase();

  for (const pattern of PRIVATE_IP_PATTERNS) {
    if (pattern.test(hostname)) {
      return {
        isValid: false,
        error: 'URLs pointing to private or local addresses are not allowed',
      };
    }
  }

  // Check blocked domains
  if (BLOCKED_DOMAINS.has(hostname)) {
    return {
      isValid: false,
      error: 'This domain is not allowed for shortening',
    };
  }

  // Check blocked TLDs
  for (const tld of BLOCKED_TLDS) {
    if (hostname.endsWith(tld)) {
      return {
        isValid: false,
        error: 'URLs with this top-level domain are not allowed',
      };
    }
  }

  // Check for suspicious patterns
  if (hostname.includes('..') || hostname.includes('--')) {
    return {
      isValid: false,
      error: 'URL contains suspicious patterns',
    };
  }

  // Ensure hostname has at least one dot (valid domain)
  if (!hostname.includes('.') && hostname !== 'localhost') {
    return {
      isValid: false,
      error: 'Invalid domain name',
    };
  }

  // Sanitize by reconstructing the URL (removes potential XSS vectors)
  const sanitizedUrl = parsedUrl.toString();

  return {
    isValid: true,
    sanitizedUrl,
  };
}

/**
 * Validates a short code for security and format compliance
 * @param shortCode - The short code to validate
 * @returns Validation result
 */
export function validateShortCode(shortCode: string): URLValidationResult {
  if (!shortCode || typeof shortCode !== 'string') {
    return { isValid: false, error: 'Short code is required' };
  }

  const trimmed = shortCode.trim();

  if (trimmed.length < 3) {
    return { isValid: false, error: 'Short code must be at least 3 characters' };
  }

  if (trimmed.length > 20) {
    return { isValid: false, error: 'Short code must be at most 20 characters' };
  }

  // Only allow alphanumeric, hyphens, and underscores
  if (!/^[a-zA-Z0-9_-]+$/.test(trimmed)) {
    return {
      isValid: false,
      error: 'Short code can only contain letters, numbers, hyphens, and underscores',
    };
  }

  // Prevent reserved words
  const reserved = ['api', 'admin', 'dashboard', 'auth', 'login', 'logout', 'signup', 'signin'];
  if (reserved.includes(trimmed.toLowerCase())) {
    return { isValid: false, error: 'This short code is reserved' };
  }

  return { isValid: true, sanitizedUrl: trimmed };
}

