/**
 * URL and ShortCode Validation Module
 * Provides comprehensive validation to prevent XSS, phishing, and malicious redirects
 */

// Blocked domains (known link shorteners, IP loggers, phishing sites)
const BLOCKED_DOMAINS = [
  // Link shorteners
  'bit.ly', 'tinyurl.com', 'goo.gl', 'ow.ly', 't.co', 'is.gd', 'buff.ly',
  'adf.ly', 'shorturl.at', 'cutt.ly', 'rb.gy', 'tiny.cc',

  // IP loggers and tracking sites
  'grabify.link', 'iplogger.org', 'iplogger.com', 'blasze.tk', 'blasze.com',
  'gyazo.nl', 'lovebird.guru', 'trulove.guru', 'dateing.club', 'shrekis.life',
  'headshot.monster', 'gaming-at-my.best', 'progaming.monster', 'yourmy.monster',
  'imageshack.com', 'leancoding.co', '2no.co', 'yip.su', 'xlogger.ru',

  // Additional suspicious domains
  'discord.gift', 'steamcommunity.ru', 'stearncommuntiy.com'
];

// Blocked TLDs (commonly used for spam/phishing)
const BLOCKED_TLDS = [
  'tk', 'ml', 'ga', 'cf', 'gq', // Free TLDs often used for abuse
  'xyz', // High abuse rate
];

// Private/local IP ranges (regex patterns)
const PRIVATE_IP_PATTERNS = [
  /^127\./,                    // Loopback
  /^10\./,                     // Private Class A
  /^172\.(1[6-9]|2\d|3[01])\./, // Private Class B
  /^192\.168\./,               // Private Class C
  /^169\.254\./,               // Link-local
  /^::1$/,                     // IPv6 loopback
  /^fe80:/,                    // IPv6 link-local
  /^fc00:/,                    // IPv6 unique local
];

// Suspicious URL patterns
const SUSPICIOUS_PATTERNS = [
  /@/,                         // Credentials in URL
  /\s/,                        // Whitespace
  /<|>/,                       // HTML tags (XSS)
  /javascript:/i,              // JavaScript protocol
  /data:/i,                    // Data URLs
  /file:/i,                    // File protocol
  /vbscript:/i,                // VBScript protocol
];

/**
 * Validation result type
 */
export type ValidationResult = {
  isValid: boolean;
  error?: string;
  sanitizedUrl?: string;
};

/**
 * Checks if a hostname is a private/local IP address
 */
function isPrivateIP(hostname: string): boolean {
  // Check IPv4 and IPv6 patterns
  return PRIVATE_IP_PATTERNS.some(pattern => pattern.test(hostname));
}

/**
 * Checks if domain is in the blocked list
 */
function isBlockedDomain(hostname: string): boolean {
  const domain = hostname.toLowerCase();
  return BLOCKED_DOMAINS.some(blocked => 
    domain === blocked || domain.endsWith(`.${blocked}`)
  );
}

/**
 * Checks if TLD is blocked
 */
function isBlockedTLD(hostname: string): boolean {
  const parts = hostname.toLowerCase().split('.');
  const tld = parts[parts.length - 1];
  return BLOCKED_TLDS.includes(tld);
}

/**
 * Checks for suspicious patterns in URL
 */
function hasSuspiciousPattern(url: string): boolean {
  return SUSPICIOUS_PATTERNS.some(pattern => pattern.test(url));
}

/**
 * Comprehensive URL validation
 * @param url - The URL to validate
 * @returns Validation result with sanitized URL if valid
 */
export function validateUrl(url: string): ValidationResult {
  // Check if URL is empty or only whitespace
  if (!url || url.trim().length === 0) {
    return {
      isValid: false,
      error: "URL is required"
    };
  }

  // Remove leading/trailing whitespace
  const trimmedUrl = url.trim();

  // Check for suspicious patterns first (before parsing)
  if (hasSuspiciousPattern(trimmedUrl)) {
    return {
      isValid: false,
      error: "URL contains suspicious or invalid characters"
    };
  }

  // Try to parse URL
  let parsedUrl: URL;
  try {
    parsedUrl = new URL(trimmedUrl);
  } catch {
    return {
      isValid: false,
      error: "Invalid URL format"
    };
  }

  // Check protocol - only allow HTTP and HTTPS
  if (parsedUrl.protocol !== 'http:' && parsedUrl.protocol !== 'https:') {
    return {
      isValid: false,
      error: "Only HTTP and HTTPS protocols are allowed"
    };
  }

  // Check for private/local IPs
  if (isPrivateIP(parsedUrl.hostname)) {
    return {
      isValid: false,
      error: "Private and local IP addresses are not allowed"
    };
  }

  // Check for blocked domains
  if (isBlockedDomain(parsedUrl.hostname)) {
    return {
      isValid: false,
      error: "This domain is not allowed (link shorteners and tracking sites are blocked)"
    };
  }

  // Check for blocked TLDs
  if (isBlockedTLD(parsedUrl.hostname)) {
    return {
      isValid: false,
      error: "This top-level domain is not allowed"
    };
  }

  // Check URL length (prevent extremely long URLs)
  if (trimmedUrl.length > 2048) {
    return {
      isValid: false,
      error: "URL is too long (maximum 2048 characters)"
    };
  }

  // Additional check: ensure hostname exists and is not empty
  if (!parsedUrl.hostname || parsedUrl.hostname.length === 0) {
    return {
      isValid: false,
      error: "URL must have a valid hostname"
    };
  }

  // All checks passed - return sanitized URL
  return {
    isValid: true,
    sanitizedUrl: parsedUrl.toString() // Use the parsed URL to ensure it's properly formatted
  };
}

/**
 * Validates a short code for URL shortening
 * @param shortCode - The short code to validate
 * @returns Validation result
 */
export function validateShortCode(shortCode: string): ValidationResult {
  // Check if shortCode is empty
  if (!shortCode || shortCode.trim().length === 0) {
    return {
      isValid: false,
      error: "Short code is required"
    };
  }

  const trimmed = shortCode.trim();

  // Check length
  if (trimmed.length < 3) {
    return {
      isValid: false,
      error: "Short code must be at least 3 characters long"
    };
  }

  if (trimmed.length > 20) {
    return {
      isValid: false,
      error: "Short code must be at most 20 characters long"
    };
  }

  // Check format - only alphanumeric, hyphens, and underscores
  if (!/^[a-zA-Z0-9_-]+$/.test(trimmed)) {
    return {
      isValid: false,
      error: "Short code can only contain letters, numbers, hyphens, and underscores"
    };
  }

  // Reserved short codes (prevent conflicts with app routes)
  const RESERVED_CODES = [
    'api', 'admin', 'dashboard', 'auth', 'login', 'logout', 'signup',
    'signin', 'register', 'profile', 'settings', 'help', 'about',
    'terms', 'privacy', 'contact', 'support', 'docs', 'blog',
  ];

  if (RESERVED_CODES.includes(trimmed.toLowerCase())) {
    return {
      isValid: false,
      error: "This short code is reserved and cannot be used"
    };
  }

  return {
    isValid: true,
    sanitizedUrl: trimmed
  };
}

/**
 * Rate Limiting Utility
 * Serverless-friendly rate limiting using in-memory Map
 * 
 * For production with multiple serverless instances, consider using:
 * - Upstash Redis for distributed rate limiting
 * - Vercel KV for persistent rate limiting
 */

interface RateLimitEntry {
  count: number;
  resetAt: number;
}

interface RateLimitConfig {
  /**
   * Maximum number of requests allowed within the window
   */
  maxRequests: number;

  /**
   * Time window in milliseconds
   */
  windowMs: number;
}

interface RateLimitResult {
  success: boolean;
  limit: number;
  remaining: number;
  resetAt: number;
}

class RateLimiter {
  private requests: Map<string, RateLimitEntry> = new Map();
  private cleanupInterval: NodeJS.Timeout | null = null;

  constructor() {
    // Clean up expired entries every minute to prevent memory leaks
    this.cleanupInterval = setInterval(() => {
      this.cleanup();
    }, 60000);
  }

  /**
   * Check if a request should be rate limited
   * @param identifier - Unique identifier (userId, IP address, etc.)
   * @param config - Rate limit configuration
   * @returns Rate limit result with success status and metadata
   */
  check(identifier: string, config: RateLimitConfig): RateLimitResult {
    const now = Date.now();
    const entry = this.requests.get(identifier);

    // If no entry exists or the window has expired, create a new one
    if (!entry || now > entry.resetAt) {
      const newEntry: RateLimitEntry = {
        count: 1,
        resetAt: now + config.windowMs,
      };
      this.requests.set(identifier, newEntry);

      return {
        success: true,
        limit: config.maxRequests,
        remaining: config.maxRequests - 1,
        resetAt: newEntry.resetAt,
      };
    }

    // Check if the request exceeds the limit
    if (entry.count >= config.maxRequests) {
      return {
        success: false,
        limit: config.maxRequests,
        remaining: 0,
        resetAt: entry.resetAt,
      };
    }

    // Increment the count
    entry.count++;
    this.requests.set(identifier, entry);

    return {
      success: true,
      limit: config.maxRequests,
      remaining: config.maxRequests - entry.count,
      resetAt: entry.resetAt,
    };
  }

  /**
   * Clean up expired entries to prevent memory leaks
   */
  private cleanup(): void {
    const now = Date.now();
    const toDelete: string[] = [];

    for (const [key, entry] of this.requests.entries()) {
      if (now > entry.resetAt) {
        toDelete.push(key);
      }
    }

    for (const key of toDelete) {
      this.requests.delete(key);
    }

    if (toDelete.length > 0) {
      console.log(`[RateLimiter] Cleaned up ${toDelete.length} expired entries`);
    }
  }

  /**
   * Clear all rate limit entries (useful for testing)
   */
  reset(): void {
    this.requests.clear();
  }

  /**
   * Cleanup resources
   */
  destroy(): void {
    if (this.cleanupInterval) {
      clearInterval(this.cleanupInterval);
      this.cleanupInterval = null;
    }
    this.requests.clear();
  }
}

